function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'Matrix3D' || !Array.isArray(args[0]) || args[0].length !== 1) return 'Start with Matrix3D(n).';
  const n = args[0][0];
  if (!Number.isInteger(n) || n < 1 || n > 100) return 'n is a whole number from 1 to 100.';
  let updates = 0;
  let queries = 0;
  for (let i = 1; i < operations.length; i++) {
    const a = args[i];
    if (operations[i] === 'setCell' || operations[i] === 'unsetCell') {
      if (!Array.isArray(a) || a.length !== 3 || a.some(v => !Number.isInteger(v) || v < 0 || v >= n)) return operations[i] + ' needs x, y and z from 0 to n - 1.';
      updates++;
    } else if (operations[i] === 'largestMatrix') {
      if (!Array.isArray(a) || a.length !== 0) return 'largestMatrix takes no arguments.';
      queries++;
    } else return 'Only setCell, unsetCell and largestMatrix can follow the constructor.';
  }
  if (updates > 100000) return 'At most 10^5 calls to setCell and unsetCell.';
  if (queries > 10000) return 'At most 10^4 calls to largestMatrix.';
  return null;
}

