class Matrix3D {
  constructor(n) {
    this.n = n;
    this.cells = new Set();
    this.count = new Array(n).fill(0);
    this.heap = [];
    for (let x = 0; x < n; x++) {
      this.push(x);
    }
  }

  setCell(x, y, z) {
    const key = (x * this.n + y) * this.n + z;
    if (this.cells.has(key)) return;
    this.cells.add(key);
    this.count[x]++;
    this.push(x);
  }

  unsetCell(x, y, z) {
    const key = (x * this.n + y) * this.n + z;
    if (!this.cells.has(key)) return;
    this.cells.delete(key);
    this.count[x]--;
    this.push(x);
  }

  largestMatrix() {
    while (this.heap[0][0] !== this.count[this.heap[0][1]]) {
      this.pop();
    }
    return this.heap[0][1];
  }

  above(a, b) {
    return a[0] > b[0] || (a[0] === b[0] && a[1] > b[1]);
  }

  push(x) {
    const heap = this.heap;
    heap.push([this.count[x], x]);
    let child = heap.length - 1;
    while (child > 0) {
      const parent = (child - 1) >> 1;
      if (!this.above(heap[child], heap[parent])) break;
      [heap[child], heap[parent]] = [heap[parent], heap[child]];
      child = parent;
    }
  }

  pop() {
    const heap = this.heap;
    const last = heap.pop();
    if (heap.length === 0) return;
    heap[0] = last;
    let parent = 0;
    while (true) {
      const left = 2 * parent + 1;
      let top = parent;
      if (left < heap.length && this.above(heap[left], heap[top])) top = left;
      if (left + 1 < heap.length && this.above(heap[left + 1], heap[top])) top = left + 1;
      if (top === parent) return;
      [heap[top], heap[parent]] = [heap[parent], heap[top]];
      parent = top;
    }
  }
}

