class Matrix3D {
  constructor(n) {
    this.n = n;
    this.matrix = Array.from({ length: n }, () => Array.from({ length: n }, () => new Array(n).fill(0)));
  }
  setCell(x, y, z) {
    this.matrix[x][y][z] = 1;
  }
  unsetCell(x, y, z) {
    this.matrix[x][y][z] = 0;
  }
  largestMatrix() {
    // Count every layer from scratch; ">=" lets a later (bigger) index win a tie.
    let best = -1;
    let bestOnes = -1;
    for (let x = 0; x < this.n; x++) {
      let ones = 0;
      for (const row of this.matrix[x]) for (const bit of row) ones += bit;
      if (ones >= bestOnes) {
        best = x;
        bestOnes = ones;
      }
    }
    return best;
  }
}

