function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const n = large ? (rand() < 0.75 ? int(40, 100) : int(2, 6)) : int(1, 4);
  const calls = large ? 499 : int(1, 16);
  // A few favourite layers collect most of the ones, so counts differ and ties shift around.
  const favourites = [int(0, n - 1), int(0, n - 1), int(0, n - 1)];
  const operations = ['Matrix3D'];
  const args = [[n]];
  const on = [];
  for (let i = 0; i < calls; i++) {
    const roll = rand();
    if (roll < 0.3) {
      operations.push('largestMatrix');
      args.push([]);
    } else if (roll < 0.55 && on.length > 0) {
      operations.push('unsetCell');
      args.push([...on.splice(Math.floor(rand() * on.length), 1)[0]]);
    } else if (roll < 0.62) {
      // Any cell at all: this may set a cell that is already 1 or clear one that is already 0.
      operations.push(rand() < 0.5 ? 'setCell' : 'unsetCell');
      args.push([int(0, n - 1), int(0, n - 1), int(0, n - 1)]);
    } else {
      const x = rand() < 0.6 ? favourites[int(0, 2)] : int(0, n - 1);
      const cell = [x, int(0, n - 1), int(0, n - 1)];
      operations.push('setCell');
      args.push([...cell]);
      on.push(cell);
    }
  }
  return [operations, args];
}
